local M = class("PetardMainView",LikeOO.OOPopBase)

M.m_uiName = "PetardActivity/PetardMain"  -- prefab name
M.m_size_type = 1
M.m_iphoneXAdapter = true

function M:onEnter()
    EventDispatcher:registerEvent(GlobalConfig.EVENT_KEYS.EVERY_DAY_EVENT, {self, self.everyDayRefreshEvent})
    EventDispatcher:registerEvent("forceRefresh_petardInfoData", {self, self.everyDayRefreshEvent})
    EventDispatcher:registerEvent("petardMainRedDotRefresh", {self, self.refreshAllRedDot})
    self.tab_Node = self.m_model.m_tabConfig
    self:bindUI()
    self:showAniNode()
   self:setUIBgAdaptive()
end

function M:setUIBgAdaptive()
    local view_width = self.m_view_width
    local view_height = self.m_view_height
    local bg_scale_w = view_width/1632
    local bg_scale_h = view_height/GlobalConfig.UI_DESIGN_HEIGHT
    local bg_scale = math.max(bg_scale_w , bg_scale_h)

    local bgObj = self:findGameObject("bg")
    local bgObj2 = self:findGameObject("bg2")
    local animObj = self:findGameObject("animNode")
    UIUtil.setLocalScale(bgObj.transform, bg_scale,bg_scale)
    UIUtil.setLocalScale(bgObj2.transform, bg_scale,bg_scale)
    UIUtil.setLocalScale(animObj.transform, bg_scale,bg_scale)
end

function M:showAniNode()
    local petard_Ani = self:findGameObject("yanhua_permanentAni")
    GameUtil:updateSpineLoadSet(petard_Ani, "RoleSpine/" .. "yanhua_SkeletonData", "animation", 0, true)
    -- 每日播放动画
    local openPlayIndex = ConfigManager:getCommonValueById(633) or 0
    -- 0 不播放，1播放
    if openPlayIndex == 0 then
        return
    end
    local isNpcAni = RedPointUtil:localRedPointJudge("PetardMainAnimEveryDayRedDot")
    if not isNpcAni then
        return
    end
    self:showAnimNode2()
end

function M:showAnimNode2()
    RedPointUtil:saveLocalRedPointFreshTime("PetardMainAnimEveryDayRedDot")
    local animNode = self:findGameObject("animNode")
    --ResourceUtil:LoadUIGameObject("PetardActivity/PetardMainAnimNode", Vector3.zero, animNode)
    local tab_cls = CustomRequire("UI.PetardActivity.PetardMain.PetardMainAnimNode")
    tab_cls.new(self.m_control, {parent = animNode})
    audio:SendEvtUI("UI_HHDShang")
end

function M:bindUI() 
    --petard_text_0001 = "签到有礼",
    --petard_text_0002 = "花火集会",
    --petard_text_0003 = "花火商城",
    --petard_text_0004 = "返现礼包",
    local petardAactivityDatas = self.m_model.petardAactivityDatas
    local nameData = petardAactivityDatas[222].xlsxActivity
    self:setTextByLanKey("text_tabBtnText1", nameData.name)
    nameData = petardAactivityDatas[223].xlsxActivity
    self:setTextByLanKey("text_tabBtnText2", nameData.name)
    nameData = petardAactivityDatas[224].xlsxActivity
    self:setTextByLanKey("text_tabBtnText3", nameData.name)
    nameData = petardAactivityDatas[306] and petardAactivityDatas[306].xlsxActivity or {name =""}
    self:setTextByLanKey("text_tabBtnText4", nameData.name)
    nameData = petardAactivityDatas[221].xlsxActivity
    self:setTextByLanKey("close_title_text", nameData.name)
    self:refreshAllRedDot()
end

-- 每日刷新
function M:everyDayRefreshEvent()
    self:updateMsg("everyDayrefresh", {index = 2})
end

function M:refreshAllRedDot()
    for _, itemData in pairs(self.tab_Node) do
        local red_point_img = self:findGameObject("red_point"..itemData.redDotIndex)
        if red_point_img then
            local openId = itemData.open_id
            local isShowRedDot = false
            if openId == 222 then
                -- 签到有礼
                local itemActivityData = self.m_model.petardAactivityDatas[openId]
                local serverData = itemActivityData.serverData
                local activityXlsxData = itemActivityData.activityData
                local openDay = GameUtil:getActityOpenDayCount(activityXlsxData.start_ts)
                local flower_loginData = ConfigManager:getCfgByName("flower_login")
                local versionData = flower_loginData[self.m_model.m_version]
                if openDay <= table.nums(versionData) and table.nums(serverData) < openDay then
                    isShowRedDot = true
                end
            elseif openId == 223 then
                -- 花火集会 
                -- 任务
                local activityData = self.m_model.petardAactivityDatas[openId].serverData
                local taskData = activityData.taskData
                for _, itemData in pairs(taskData) do
                    if itemData.status == 1 then
                        isShowRedDot = true
                        break
                    end
                end
                -- 积分
                if not isShowRedDot then
                    local flower_rewardData = ConfigManager:getCfgByName("flower_reward")
                    local versionData = flower_rewardData[self.m_model.m_version]
                    local canGotCount = 0
                    local curValue = activityData.score
                    local serverGotCount = table.nums(activityData.scoreTaskData)
                    for i = 1, #versionData do
                        local itemData = versionData[i]
                        if curValue >= itemData.score then
                            canGotCount = canGotCount + 1
                        end
                    end
                    isShowRedDot = (canGotCount > serverGotCount)
                end
            elseif openId == 224 then
                -- 花火商城
                isShowRedDot = RedPointUtil:localRedPointJudge("petardShop_everyDayRedDot")
            elseif openId == 306 and self.m_model.petardAactivityDatas[openId] then
                -- 返现礼包
                isShowRedDot = RedPointUtil:localRedPointJudge("TongYongFanLiRedDot")
                if isShowRedDot then
                    local serverData = self.m_model.petardAactivityDatas[openId].serverData
                    local skinDataCount = table.nums(serverData.clothes_done)
                    local giftDataCount = table.nums(serverData.gift_log)
                    if skinDataCount >= 1 and giftDataCount >= 3 then
                        -- 郭鹏说，每日首亮，如果四个礼包都买了就不亮子活动的小红点了
                        isShowRedDot = false
                    end
                end
            end
            red_point_img:SetActive(isShowRedDot)
        end
    end
end

function M:destroy()
    self.m_control:testOpenByActivityTimer()
    EventDispatcher:unRegisterEvent(GlobalConfig.EVENT_KEYS.EVERY_DAY_EVENT, {self, self.everyDayRefreshEvent})
    EventDispatcher:unRegisterEvent("forceRefresh_petardInfoData", {self, self.everyDayRefreshEvent})
    EventDispatcher:unRegisterEvent("petardMainRedDotRefresh", {self, self.refreshAllRedDot})
    M.super.destroy(self)
end

return M